package com.example.bodega.usuario.controller;
import com.example.bodega.common.dto.EstadoRequest; import com.example.bodega.usuario.dto.*; import com.example.bodega.usuario.service.UsuarioService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/usuarios") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class UsuarioController {private final UsuarioService service;@GetMapping public List<UsuarioResponse> listar(){return service.listar();}@GetMapping("/{id}") public UsuarioResponse obtener(@PathVariable Long id){return service.obtener(id);}@PostMapping public ResponseEntity<UsuarioResponse> crear(@Valid @RequestBody UsuarioRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(r));}@PutMapping("/{id}") public UsuarioResponse actualizar(@PathVariable Long id,@Valid @RequestBody UsuarioRequest r){return service.actualizar(id,r);}@PatchMapping("/{id}/estado") public UsuarioResponse estado(@PathVariable Long id,@Valid @RequestBody EstadoRequest r){return service.cambiarEstado(id,r.activo());}@PatchMapping("/{id}/desactivar") @ResponseStatus(HttpStatus.NO_CONTENT) public void desactivar(@PathVariable Long id){service.desactivar(id);}}
